2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/11533/amerikaanse-goden.html","sha256":"42e4db5b9e68fb0b62d0dfbaebcd8422c2e096fce6618c49396c9237ac053568","checkedAt":"2026-11-01T14:00:13.010Z","fact":"Paperback ISBN 9789022568699 verschijningsdatum 18/04/2017 NUR 334 Fantasy 302 Vertaalde literaire roman, novelle imprint Boekerij uitgever Meulenhoff Boekerij B.V. taal Nederlands","sourceAuthors":"Neil Gaiman","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789048857432","key":{"id":977200106},"before":null,"after":{"work_id":977100022,"title":"Blade Runner","language":"nld","isbn_13":"9789048857432","isbn_10":null,"open_library_edition_id":null,"publisher":"Overamstel Uitgevers","id":977200106}},{"relation":"catalog_edition_metadata","ref":"metadata:9789048857432","key":{"edition_id":"@edition:9789048857432"},"before":null,"after":{"edition_id":"@edition:9789048857432","work_id":977100022,"bound_author_id":977300005,"bound_title":"Blade Runner","bound_language":"nld","bound_isbn13":"9789048857432","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000344923_Blade_Runner_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/979376/blade-runner.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/979376/blade-runner.html","sha256":"c8210213e3372db9ec60cdbf20fe604c488ae222964d005b26137e5b8e170438","checkedAt":"2026-11-01T14:00:15.224Z","fact":"Paperback ISBN 9789048857432 verschijningsdatum 10/03/2020 NUR 302 Vertaalde literaire roman, novelle imprint Lebowski uitgever Overamstel Uitgevers taal Nederlands","sourceAuthors":"Philip K Dick , Philip Kindred Dick","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."},{"url":"https://metadata.isbn.nl/ie_fcache/0000344923_Blade_Runner_0_0.jpg","sha256":"bcba18219303a7ce079c5153a9b50584293a9e02f0c567ae7757e90350ee3a6e","bytes":45561,"checkedAt":"2026-11-01T14:19:46.313Z","fact":"Exact ISBN block image + human visual title/author review, sheet2"}]}},{"relation":"catalog_work_descriptions","ref":"description:31","key":{"work_id":977100022,"language":"nl"},"before":null,"after":{"work_id":977100022,"language":"nl","bound_author_id":977300005,"text":"Na een verwoestende oorlog ligt San Francisco onder radioactief stof. Wie over voldoende middelen beschikt, kan de aarde verlaten en androïden als hulp meenemen. Wanneer zulke kunstmatige wezens in opstand komen, krijgt Rick Deckard de opdracht hen uit te schakelen. Zijn onderzoek brengt hem bij de mensen die hen ontwerpen. Het onderscheid tussen mens en machine draait daarbij niet alleen om uiterlijk, maar ook om empathie en de betekenis daarvan.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/979376/blade-runner.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/979376/blade-runner.html","sha256":"c8210213e3372db9ec60cdbf20fe604c488ae222964d005b26137e5b8e170438","checkedAt":"2026-11-01T14:00:15.224Z","fact":"Paperback ISBN 9789048857432 verschijningsdatum 10/03/2020 NUR 302 Vertaalde literaire roman, novelle imprint Lebowski uitgever Overamstel Uitgevers taal Nederlands","sourceAuthors":"Philip K Dick , Philip Kindred Dick","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789041711298","key":{"id":977200107},"before":null,"after":{"work_id":977100023,"title":"Woeste Hoogten","language":"nld","isbn_13":"9789041711298","isbn_10":null,"o