langen naar vergelding dat verder reikt dan hun eigen verhouding en ook andere bewoners van het landgoed treft.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/272848/de-woeste-hoogte.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/272848/de-woeste-hoogte.html","sha256":"7e894bd5b983a596e33308207fd5cf1d0de64fd20de00de55ec008cf19a23992","checkedAt":"2026-11-01T14:00:19.422Z","fact":"Paperback ISBN 9789041711298 verschijningsdatum 05/08/2014 NUR 302 Vertaalde literaire roman, novelle imprint Rainbow uitgever Uitgeverij Rainbow bv taal Nederlands","sourceAuthors":"Emily Bronte","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789020415605","key":{"id":977200108},"before":null,"after":{"work_id":977100024,"title":"Moby Dick","language":"nld","isbn_13":"9789020415605","isbn_10":null,"open_library_edition_id":null,"publisher":"Atlas Contact, Uitgeverij","id":977200108}},{"relation":"catalog_edition_metadata","ref":"metadata:9789020415605","key":{"edition_id":"@edition:9789020415605"},"before":null,"after":{"edition_id":"@edition:9789020415605","work_id":977100024,"bound_author_id":977300007,"bound_title":"Moby Dick","bound_language":"nld","bound_isbn13":"9789020415605","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000249310_Moby_Dick_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1041417/moby-dick.html","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1041417/moby-dick.html","sha256":"27c0ec61a3f461b4ea1de8118f844f083ecda5f7ec753b26ab6bbf3633a0e970","checkedAt":"