k_id":977100025,"language":"nl","bound_author_id":977300008,"text":"Holden Caulfield is van school gestuurd en durft dat niet aan zijn ouders te vertellen. In de dagen rond Kerstmis zwerft hij daarom door New York, waar hij mensen ontmoet maar zich vaak niet met hen verbonden voelt. Alleen bij zijn kleine zusje ervaart hij volledig vertrouwen. Zijn vertelling volgt zijn onrust en zijn moeite met de volwassen wereld, waarin hij oprechtheid en onschuld dreigt kwijt te raken.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/832620/de-vanger-in-het-graan.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/832620/de-vanger-in-het-graan.html","sha256":"107b2eb5d6b0d2d4e4048f598c57eee729d1525c2483eff76f3a5b478651315e","checkedAt":"2026-11-01T14:00:29.389Z","fact":"Paperback ISBN 9789403134109 Nieuwe editie verschijningsdatum 14/01/2019 NUR 302 Vertaalde literaire roman, novelle uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sourceAuthors":"J.D. Salinger","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789025440589","key":{"id":977200110},"before":null,"after":{"work_id":977100026,"title":"De druiven der gramschap","language":"nld","isbn_13":"9789025440589","isbn_10":null,"open_library_edition_id":null,"publisher":"Atlas Contact, Uitgeverij","id":977200110}},{"relation":"catalog_edition_metadata","ref":"metadata:9789025440589","key":{"edition_id":"@edition:9789025440589"},"before":null,"after":{"edition_id":"@edition:9789025440589","work_id":977100026,"bound_author_id":977300009,"bound_title":"De druiven der gramschap","bound_language":"nld","bound_isbn13":"9789025440589","format":"paperback","cover_url":"https://